/// `SSRA_asisdshf_R`.
///
/// Cut: ENV, V_read, V_set.
pub(super) fn SSRA_asisdshf_R(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::SSRA_asisdshf_R;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 0) & 0x1f;
    let s2: u128 = (w >> 5) & 0x1f;
    let s3: u128 = (w >> 16) & 0x7;
    let s4: u128 = (w >> 19) & 0xf;
    let s5: i128 = s1 as i128;
    let s6: i128 = s2 as i128;
    let s7: u128 = (s4 >> 3) & 0x1;
    let s8: bool = s7 != 0x1u128;
    if s8 {
        return Err(LiftError::Undefined(ENC));
    }
    let s9: bool = !s8;
    let s10: u128 = (s4 << 3) | s3;
    let s11: i128 = s10 as i128;
    let s12: i128 = (128i128).wrapping_sub(s11);
    let v13 = st.v_read(b, s6 as u32, 64);
    let v14 = st.v_read(b, s5 as u32, 64);
    let v15 = b.sext(v13, Width::W128);
    let v16 = b.konst(Width::new(128), (s12) as u128);
    let v17 = b.bin(BinOp::AShr, v15, v16);
    let v18 = b.extract(v17, 0, Width::new(64));
    let v19 = b.bin(BinOp::Add, v14, v18);
    if s9 {
        st.v_set(b, s5 as u32, v19, None);
    }
    Ok(())
}

